package main
import (
  "fmt"
  "sync"
)
func main() {
  var wg sync.WaitGroup
  var m sync.Mutex
  x := 0
  for i := 0; i < 3; i++ {
    wg.Add(1)
    go func() {
      m.Lock()
      x++
      m.Unlock()
      wg.Done()
    }()
  }
  wg.Wait()
  fmt.Println(x)
}

